window.CARD_EXPORT_RESOURCES = {"images":{"assets/traci-logo-on-dark.png":"data:image/png;base64,","assets/embuilded-logo.svg":"data:image/svg+xml;base64,","assets/embuilded-logo.png":"data:image/png;base64,"},"css":":root {\n  --ink: #101820;\n  --ink-soft: #29323a;\n  --gold: #f5ad00;\n  --gold-bright: #ffb800;\n  --paper: #fff;\n  --canvas: #eef0f2;\n  --line: #dfe3e6;\n  --muted: #6f777d;\n  --panel: #f9fafb;\n  --shadow: 0 18px 50px rgba(16, 24, 32, .12);\n  --radius: 14px;\n}\n\n* { box-sizing: border-box; }\n\nhtml { min-width: 320px; }\n\nbody {\n  margin: 0;\n  color: var(--ink);\n  background: var(--canvas);\n  font-family: \"DM Sans\", \"Noto Sans TC\", system-ui, sans-serif;\n  -webkit-font-smoothing: antialiased;\n}\n\nbutton, input { font: inherit; }\nbutton { color: inherit; }\n\n.topbar {\n  height: 66px;\n  padding: 0 28px;\n  display: flex;\n  align-items: center;\n  gap: 20px;\n  background: var(--ink);\n  color: #fff;\n  border-bottom: 3px solid var(--gold);\n}\n\n.brand {\n  display: inline-flex;\n  align-items: center;\n  gap: 10px;\n  color: inherit;\n  text-decoration: none;\n  font-weight: 700;\n  letter-spacing: .02em;\n}\n\n.brand-mark {\n  width: 31px;\n  height: 31px;\n  display: grid;\n  place-items: center;\n  color: var(--gold-bright);\n  border: 2px solid var(--gold-bright);\n  border-right: 0;\n  font-weight: 700;\n}\n\n.save-state {\n  margin-left: auto;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  color: #c9ced2;\n  font-size: 13px;\n}\n\n.status-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: #58c78a;\n  box-shadow: 0 0 0 4px rgba(88, 199, 138, .12);\n}\n\n.help-button {\n  padding: 7px 12px;\n  color: #e7e9eb;\n  background: transparent;\n  border: 1px solid #46505a;\n  border-radius: 7px;\n  cursor: pointer;\n}\n\n.help-button:hover { border-color: #7a838a; }\n\n.workspace {\n  min-height: calc(100vh - 66px);\n  display: grid;\n  grid-template-columns: minmax(330px, 430px) minmax(620px, 1fr);\n}\n\n.editor-panel {\n  background: var(--paper);\n  border-right: 1px solid var(--line);\n  padding: 38px 34px 60px;\n}\n\n.panel-heading { margin-bottom: 34px; }\n.eyebrow {\n  margin: 0 0 6px;\n  color: #a16f00;\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: .18em;\n}\n\nh1, h2, p { margin-top: 0; }\nh1 { margin-bottom: 10px; font-size: 28px; line-height: 1.25; letter-spacing: -.025em; }\n.panel-heading \u003e p:last-child { margin: 0; color: var(--muted); font-size: 14px; line-height: 1.6; }\n\n.form-section { padding: 0 0 28px; margin-bottom: 28px; border-bottom: 1px solid var(--line); }\n.form-section:last-child { margin-bottom: 0; }\n.section-title-row { display: flex; align-items: center; gap: 10px; margin-bottom: 18px; }\n.section-title-row h2 { margin: 0; font-size: 15px; font-weight: 700; }\n.section-number { color: var(--gold); font-size: 11px; font-weight: 700; letter-spacing: .08em; }\n.field-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 15px; }\n.field-full { grid-column: 1 / -1; }\n.field { display: grid; gap: 7px; color: #495159; font-size: 12px; font-weight: 600; }\n.field input {\n  width: 100%;\n  padding: 10px 11px;\n  color: var(--ink);\n  background: #fff;\n  border: 1px solid #d5dadd;\n  border-radius: 7px;\n  outline: none;\n  transition: border-color .15s, box-shadow .15s;\n}\n.field input:focus { border-color: #b17b00; box-shadow: 0 0 0 3px rgba(245, 173, 0, .14); }\n.field small { color: #8a9196; font-weight: 400; line-height: 1.4; }\n\n.preview-panel {\n  min-width: 0;\n  padding: 38px clamp(24px, 4vw, 60px) 50px;\n  display: flex;\n  flex-direction: column;\n}\n\n.preview-toolbar { display: flex; align-items: end; justify-content: space-between; gap: 24px; margin-bottom: 24px; }\n.preview-toolbar h2 { margin: 0; font-size: 21px; }\n.side-switcher { display: inline-flex; padding: 3px; background: #dde1e4; border-radius: 8px; }\n.side-button {\n  min-width: 66px;\n  padding: 7px 12px;\n  background: transparent;\n  border: 0;\n  border-radius: 6px;\n  color: #687078;\n  font-size: 13px;\n  font-weight: 600;\n  cursor: pointer;\n}\n.side-button.active { color: var(--ink); background: #fff; box-shadow: 0 1px 4px rgba(16,24,32,.12); }\n\n.preview-stage {\n  width: 100%;\n  min-height: 488px;\n  display: grid;\n  place-items: center;\n  padding: 34px;\n  overflow: hidden;\n  background-color: #e3e6e8;\n  background-image: linear-gradient(45deg, rgba(255,255,255,.38) 25%, transparent 25%), linear-gradient(-45deg, rgba(255,255,255,.38) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(255,255,255,.38) 75%), linear-gradient(-45deg, transparent 75%, rgba(255,255,255,.38) 75%);\n  background-size: 26px 26px;\n  background-position: 0 0, 0 13px, 13px -13px, -13px 0;\n  border: 1px solid #d6dade;\n  border-radius: var(--radius);\n}\n\n.card-scaler { width: 720px; height: 348px; position: relative; }\n.business-card {\n  position: relative;\n  width: 720px;\n  height: 348px;\n  overflow: hidden;\n  font-family: \"DM Sans\", \"Noto Sans TC\", sans-serif;\n  box-shadow: var(--shadow);\n}\n\n.card-front { background: #fff; color: #111820; }\n.front-watermark {\n  position: absolute;\n  z-index: 0;\n  top: 0;\n  right: 0;\n  width: 120px;\n  height: 310px;\n}\n.front-left { position: absolute; z-index: 1; left: 36px; top: 28px; width: 337px; }\n.embuilded-logo { position: relative; width: 350px; height: 98px; overflow: visible; }\n.embuilded-logo img { display: block; width: 350px; height: 98px; object-fit: contain; object-position: left top; }\n.identity { margin-top: 2px; }\n.name-en { font-size: 34px; line-height: 1.07; font-weight: 700; letter-spacing: -.8px; white-space: nowrap; }\n.name-zh { margin-top: 2px; font-size: 21px; line-height: 1.2; font-weight: 700; }\n.gold-rule { display: block; width: 43px; height: 3px; margin: 8px 0 7px; background: var(--gold); }\n.job-title { font-size: 20px; line-height: 1.2; }\n.contact-list { margin-top: 16px; display: grid; gap: 5px; }\n.contact-row { display: grid; grid-template-columns: 53px 1fr; align-items: center; font-size: 17px; line-height: 1.2; }\n.contact-row span { white-space: nowrap; }\n.contact-icon { width: 24px; height: 24px; }\n.front-right { position: absolute; z-index: 1; top: 126px; left: 400px; width: 185px; text-align: center; }\n.vertical-line { position: absolute; left: -24px; top: 6px; width: 1px; height: 161px; background: #aeb3b6; }\n.qr-shell { position: relative; width: 128px; height: 128px; margin: 0 auto 4px; display: grid; place-items: center; background: #fff; }\n.qr-code { width: 128px; height: 128px; }\n.qr-code img, .qr-code canvas { display: block; width: 128px !important; height: 128px !important; }\n.company-name { font-size: 12px; font-weight: 700; line-height: 1.25; white-space: nowrap; }\n.website { margin-top: 4px; font-size: 12px; letter-spacing: .045em; white-space: nowrap; }\n.front-tagline { position: absolute; z-index: 1; left: 36px; right: 44px; bottom: 20px; display: flex; align-items: center; gap: 14px; }\n.front-tagline span { width: 46px; height: 3px; flex: none; background: var(--gold); }\n.front-tagline strong { min-width: 0; font-size: 10px; font-weight: 500; letter-spacing: .24em; white-space: nowrap; }\n\n.card-back { color: #fff; background: linear-gradient(110deg, #252b2f, #171c1f); }\n.card-back[hidden], .card-front[hidden] { display: none; }\n.back-grid {\n  position: absolute;\n  right: 0;\n  bottom: 0;\n  width: 112px;\n  height: 176px;\n}\n.traci-lockup { position: absolute; left: 48px; right: 48px; top: 76px; text-align: center; }\n.traci-symbol { position: relative; width: 254px; height: 38px; overflow: hidden; margin: 0 auto; }\n.traci-symbol img { position: absolute; width: 299px; max-width: none; height: auto; left: -14px; top: -1px; }\n.traci-terms { display: flex; align-items: center; justify-content: space-between; margin-top: 22px; font-size: 10px; letter-spacing: 2px; font-weight: 400; color: #e6e8e9; }\n.traci-terms i { width: 1px; height: 20px; background: var(--gold); }\n.back-footer { position: absolute; left: 42px; right: 145px; bottom: 35px; }\n.back-rule { display: block; width: 100%; height: 1px; background: #bec3c5; }\n.back-footer p { display: flex; align-items: center; gap: 18px; margin: 16px 0 0; font-size: 12px; letter-spacing: .015em; white-space: nowrap; }\n.footer-divider { width: 1px; height: 20px; flex: none; background: var(--gold); }\n\n.actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 22px; }\n.button {\n  min-height: 41px;\n  padding: 9px 15px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  color: var(--ink);\n  background: #fff;\n  border: 1px solid #ccd2d6;\n  border-radius: 8px;\n  font-size: 13px;\n  font-weight: 700;\n  cursor: pointer;\n  transition: transform .12s, box-shadow .12s, border-color .12s;\n}\n.button:hover { transform: translateY(-1px); border-color: #aab2b8; box-shadow: 0 4px 10px rgba(16,24,32,.08); }\n.button-primary { color: var(--ink); background: var(--gold-bright); border-color: var(--gold-bright); }\n.button-vector { color: #fff; background: var(--ink); border-color: var(--ink); }\n.button-quiet { color: #657078; background: transparent; }\n.file-button input { position: absolute; width: 1px; height: 1px; overflow: hidden; opacity: 0; }\n.export-note { margin: 12px 0 0; color: #7b8389; font-size: 12px; }\n.toast {\n  position: fixed;\n  left: 50%;\n  bottom: 24px;\n  z-index: 20;\n  max-width: calc(100% - 32px);\n  padding: 10px 16px;\n  color: #fff;\n  background: #101820;\n  border-radius: 8px;\n  box-shadow: 0 10px 30px rgba(0,0,0,.22);\n  font-size: 13px;\n  opacity: 0;\n  pointer-events: none;\n  transform: translate(-50%, 12px);\n  transition: opacity .18s, transform .18s;\n}\n.toast.show { opacity: 1; transform: translate(-50%, 0); }\n\n@media (max-width: 1120px) {\n  .workspace { grid-template-columns: 350px minmax(0, 1fr); }\n  .editor-panel { padding-left: 25px; padding-right: 25px; }\n  .preview-panel { padding-left: 24px; padding-right: 24px; }\n}\n\n@media (max-width: 900px) {\n  .workspace { display: block; }\n  .editor-panel { border-right: 0; border-bottom: 1px solid var(--line); }\n  .preview-stage { min-height: 340px; }\n}\n\n@media (max-width: 560px) {\n  .topbar { height: 60px; padding: 0 16px; }\n  .save-state { display: none; }\n  .editor-panel, .preview-panel { padding: 26px 18px 38px; }\n  .field-grid { grid-template-columns: 1fr; }\n  .preview-toolbar { align-items: center; }\n  .preview-stage { min-height: 250px; padding: 16px; border-radius: 10px; }\n  .actions { display: grid; grid-template-columns: 1fr 1fr; }\n  .button { width: 100%; }\n  .export-note { line-height: 1.5; }\n}\n\n@media print {\n  body { background: #fff; }\n  .topbar, .editor-panel, .preview-toolbar, .actions, .export-note { display: none !important; }\n  .workspace, .preview-panel, .preview-stage { display: block; padding: 0; margin: 0; background: #fff; border: 0; }\n  .card-scaler { transform: none !important; }\n  .business-card { box-shadow: none; page-break-after: always; }\n}\n"};